const graph = RelayerGraphClient.fromEnv();
const interactionNode = 25;
await graph.getNode(interactionNode);
await graph.getNeighbors(interactionNode);
await graph.getInteractionInput();
const acceptedPresentation = await graph.getNodePresentation(22);
const acceptedNode = acceptedPresentation.node;
const acceptedInvoke = acceptedPresentation.actions.find((action) =>
  action.kind === 'invoke' &&
  action.clientKey === 'draft-rollout-recommendation' &&
  action.label === 'Draft rollout recommendation'
